#!/bin/bash
# usage: runloc.sh <locale-spec-label> <env-setting...> -- <case-id> [argv...]
CPP=/workspace/dataset/test10_executable
RS=/tmp/argv-audit/rs_test10
mode="$1"; shift
id="$1"; shift
d=/tmp/argv-audit/cases/"loc_${mode}__${id}"
mkdir -p "$d"
case "$mode" in
  C)        pre=(env LC_ALL=C LANG=C) ;;
  CUTF8)    pre=(env LC_ALL=C.UTF-8 LANG=C.UTF-8) ;;
  TRUTF8)   pre=(env LC_ALL=tr_TR.UTF-8 LANG=tr_TR.UTF-8) ;;
  TRUTF8L)  pre=(env LC_ALL=tr_TR.utf8 LANG=tr_TR.utf8) ;;
  TRISO)    pre=(env LC_ALL=tr_TR.iso88599 LANG=tr_TR.iso88599) ;;
  NOLANG)   pre=(env -u LANG -u LC_ALL -u LC_CTYPE -u LC_NUMERIC) ;;
  NUMDE)    pre=(env LC_ALL=de_DE.UTF-8) ;;
  BOGUS)    pre=(env LC_ALL=xx_XX.bogus LANG=xx_XX.bogus) ;;
  *) echo "bad mode"; exit 2 ;;
esac
"${pre[@]}" "$CPP" "$@" >"$d/cpp.out" 2>"$d/cpp.err"; ce=$?
"${pre[@]}" "$RS"  "$@" >"$d/rs.out"  2>"$d/rs.err";  re=$?
status=OK
cmp -s "$d/cpp.out" "$d/rs.out" || status="STDOUT_DIFF"
[ "$ce" != "$re" ] && status="$status+EXIT_DIFF"
cmp -s "$d/cpp.err" "$d/rs.err" || status="$status+STDERR_DIFF"
printf '%-14s %-22s %-30s cpp[%s,%sB] rs[%s,%sB]\n' "$mode" "$id" "$status" "$ce" "$(wc -c <"$d/cpp.out")" "$re" "$(wc -c <"$d/rs.out")"
